// Writes the made-up long job as the web sees it (web/src/jobpage/fixtures/longJob.ts, the 52-item
// job, and longJob200.ts, the 200-item one) from the server fixture (long-job.js) through
// lib/job-payload.js buildJobPage, so the two never drift. Run it after changing long-job.js:
//
//   node dashboard/test/fixtures/write-long-job.js
//
// dashboard/test/long-job-fixture.test.js fails while a written file is out of date.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { longJobPage } from './long-job.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
export const WEB_FIXTURES = path.join(ROOT, 'web', 'src', 'jobpage', 'fixtures');
export const WEB_FILES = { 52: 'longJob.ts', 200: 'longJob200.ts' };
const NAMES = { 52: 'longJob', 200: 'longJob200' };

const HEAD = [
  '// Generated by dashboard/test/fixtures/write-long-job.js from dashboard/test/fixtures/long-job.js: do not edit.',
  '// Change the server fixture, then run `node dashboard/test/fixtures/write-long-job.js`',
  '// (dashboard/test/long-job-fixture.test.js fails while this file is out of date).',
  '//',
  '// A made-up long job as the page sees it: the payload (GET /api/job/:slug/page), the bodies by id',
  '// (GET /api/job/:slug/item: { id, kind, html, text, meta }) and the Build step\'s commits. Every word',
  '// is invented. Tests only: nothing outside a test imports web/src/jobpage/fixtures.',
];

const TYPES = [
  'export type LongJobBody = { id: string; kind: string; html: string; text: string; meta: Record<string, unknown> };',
  'export type LongJobLine = {',
  '  id: string; kind: \'reply\' | \'you\' | \'brief\' | \'problem\' | \'small\'; at: string | null; step: string | null;',
  '  headline: string; mine: boolean; hash: string; answered?: string | boolean; by?: \'auto\';',
  '};',
  'export type LongJobOutput = { kind: string; id: string; label: string; meta: string | null; version: string | null };',
  'export type LongJobStep = {',
  '  id: string; label: string; state: \'done\' | \'current\' | \'todo\' | \'skipped\'; word: string | null;',
  '  durationMs: number | null; startedAt: string | null; outputs: LongJobOutput[];',
  '  main: { kind: string; id: string }; more: LongJobOutput[];',
  '};',
  '/** The payload; web/src/jobpage/types.ts has its whole type once it exists. */',
  'export type LongJobPayload = { slug: string; title: string; state: string; thread: LongJobLine[]; steps: LongJobStep[]; [key: string]: unknown };',
  'export type LongJobCommit = {',
  '  sha: string; short: string; author: string; date: string; subject: string; step: string;',
  '  files: { path: string; added: number; removed: number; isNew: boolean }[];',
  '};',
  'export type LongJobFixture = { counts: Record<string, number>; payload: LongJobPayload; bodies: Record<string, LongJobBody>; commits: LongJobCommit[] };',
];

/** The .ts file's whole text for one size. */
export function webFixture(size) {
  const { counts, payload, bodies, commits } = longJobPage({ size });
  const j = (v) => JSON.stringify(v);
  const indent = (text, by) => text.split('\n').join(`\n${by}`);
  const lines = [
    ...HEAD,
    '',
    ...(size === 52 ? TYPES : ['import type { LongJobFixture } from \'./longJob\';']),
    '',
    `export const ${NAMES[size]}: LongJobFixture = {`,
    `  counts: ${j(counts)},`,
    `  payload: ${indent(JSON.stringify(payload, null, 2), '  ')},`,
    '  bodies: {',
    ...Object.entries(bodies).map(([id, b]) => `    ${j(id)}: ${j(b)},`),
    '  },',
    '  commits: [',
    ...commits.map((c) => `    ${j(c)},`),
    '  ],',
    '};',
    '',
  ];
  return lines.join('\n');
}

const isMain = (() => {
  try { return Boolean(process.argv[1]) && fs.realpathSync(process.argv[1]) === fs.realpathSync(fileURLToPath(import.meta.url)); } catch { return false; }
})();

if (isMain) {
  fs.mkdirSync(WEB_FIXTURES, { recursive: true });
  for (const [size, file] of Object.entries(WEB_FILES)) {
    const text = webFixture(Number(size));
    fs.writeFileSync(path.join(WEB_FIXTURES, file), text);
    console.log(`Wrote web/src/jobpage/fixtures/${file} (${Math.round(Buffer.byteLength(text) / 1024)} KB).`);
  }
}
